SELECT 
FROM TBL_DERIVATIVES_CONTRACTS
WHERE CONTRACTNO = #{contractNo} AND ORGID = #{orgId}

SELECT 
FROM TBL_DERIVATIVES_CONTRACTS
WHERE ORGID = #{orgId}
AND CONTRACTSTATUS IN ('ACTIVE', 'DRAFT')
AND MATURITYDATE BETWEEN CURRENT_DATE AND CURRENT_DATE + #{days}
ORDER BY MATURITYDATE ASC

SELECT 
FROM TBL_DERIVATIVES_CONTRACTS


        AND ORGID = #{params.orgId}


        AND CONTRACTTYPE = #{params.contractType}


        AND UNDERLYINGTYPE = #{params.underlyingType}


        AND CONTRACTSTATUS = #{params.contractStatus}


        AND COUNTERPARTY LIKE CONCAT('%', #{params.counterparty}, '%')


        AND CONTRACTDATE >= #{params.startDate}


        AND CONTRACTDATE <= #{params.endDate}


        AND (CONTRACTNO LIKE CONCAT('%', #{params.keyword}, '%')
        OR CONTRACTNAME LIKE CONCAT('%', #{params.keyword}, '%')
        OR COUNTERPARTY LIKE CONCAT('%', #{params.keyword}, '%'))


ORDER BY CREATETIME DESC

SELECT COALESCE(SUM(NOTIONALAMOUNT), 0)
FROM TBL_DERIVATIVES_CONTRACTS
WHERE ORGID = #{orgId}

SELECT COALESCE(SUM(MARKETVALUE), 0)
FROM TBL_DERIVATIVES_CONTRACTS
WHERE ORGID = #{orgId}

SELECT COALESCE(SUM(UNREALIZEDPNL), 0)
FROM TBL_DERIVATIVES_CONTRACTS
WHERE ORGID = #{orgId}

SELECT COALESCE(SUM(REALIZEDPNL), 0)
FROM TBL_DERIVATIVES_CONTRACTS
WHERE ORGID = #{orgId}

SELECT 
FROM TBL_DERIVATIVES_CONTRACTS
WHERE ORGID = #{orgId}
AND NOTIONALAMOUNT >= #{threshold}
ORDER BY NOTIONALAMOUNT DESC

mapper.update:
UPDATE TBL_DERIVATIVES_CONTRACTS
SET CONTRACTSTATUS = #{status},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE CONTRACTID IN

    #{id}

UPDATE TBL_DERIVATIVES_CONTRACTS
SET UNREALIZEDPNL = #{unrealizedPnl},
    REALIZEDPNL = #{realizedPnl},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE CONTRACTID = #{contractId}

